CREATE TABLE IF NOT EXISTS nk_users(id BIGSERIAL PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,points INT NOT NULL DEFAULT 0,lifetime_points INT NOT NULL DEFAULT 0,wins INT NOT NULL DEFAULT 0,losses INT NOT NULL DEFAULT 0,unlocks JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS nk_matches(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id BIGINT REFERENCES nk_users(id) ON DELETE CASCADE,opponent TEXT NOT NULL,result TEXT NOT NULL,round_score JSONB DEFAULT '[]',max_combo INT DEFAULT 0,super_hits INT DEFAULT 0,points_awarded INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS nk_point_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES nk_users(id) ON DELETE CASCADE,amount INT NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());